# Ensure we have the list
if isinstance(pristine, dict):
    drafts = pristine.get('drafts', pristine.get('results', []))
else:
    drafts = pristine

# Build a mutable copy keyed by draft_id
draft_map = {}
for d in drafts:
    draft_map[d['draft_id']] = deepcopy(d)

# Apply writes in order
for w in data['writes']:
    api = w['api']
    args = w['args']
    result = json_value(w['result'])
    if api == 'upload_attachments_to_draft':
        did = args['draft_id']
        if did in draft_map:
            for att in result.get('attachments', []):
                draft_map[did]['attachments'].append({'file_name': att['file_name'], 'id': att['id']})
    elif api == 'remove_attachment_from_draft':
        did = args['draft_id']
        aid = args['attachment_id']
        if did in draft_map:
            draft_map[did]['attachments'] = [a for a in draft_map[did]['attachments'] if a['id'] != aid]

# Reconstruct list preserving original order
final_drafts = [draft_map[d['draft_id']] for d in drafts if d['draft_id'] in draft_map]

# The response schema for show_drafts is typically {"drafts": [...]}
print(json.dumps({"drafts": final_drafts}))

